/* Calculators section: all calculators.
   Loaded by index.html when this section is opened. Upload it next to index.html. */
/* ---------- Calculators: a separate section with many small calculators ---------- */
const CALC=[],CALCI={};
const CCATS=[['fin','Financial'],['fit','Fitness and health'],['math','Math'],['oth','Everyday and other']];
const cN=(x,d=2)=>typeof x==='number'&&isFinite(x)?x.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const cG=(x,d=6)=>typeof x==='number'&&isFinite(x)?String(+x.toPrecision(d)):'—';
const cP=(x,d=2)=>cN(x,d)+'%';
const cYM=m=>{if(!isFinite(m))return'—';m=Math.round(m);const y=Math.floor(m/12),r=m%12;return ((y?y+' year'+(y===1?'':'s')+' ':'')+(r||!y?r+' month'+(r===1?'':'s'):'')).trim()};
const N=(id,l,d,o)=>({k:'n',id,l,d,...o}),S=(id,l,opts,d,o)=>({k:'s',id,l,opts:opts.map(x=>typeof x==='string'?[x,x]:x),d:d===undefined?(typeof opts[0]==='string'?opts[0]:opts[0][0]):d,...o});
const X=(id,l,d,o)=>({k:'t',id,l,d,...o}),XA=(id,l,d,o)=>({k:'a',id,l,d,...o}),DA=(id,l,d,o)=>({k:'d',id,l,d,...o}),DT=(id,l,d,o)=>({k:'dt',id,l,d,...o}),TM=(id,l,d,o)=>({k:'tm',id,l,d,...o}),U=(id,l,d,units,o)=>({k:'u',id,l,d,units,...o});
const UW=[['kg',1],['lb',0.45359237]],UH=[['cm',1],['in',2.54],['ft',30.48]],UL=[['km',1000],['m',1],['mi',1609.344],['ft',0.3048]],UM=[['m',1],['cm',0.01],['ft',0.3048],['in',0.0254],['yd',0.9144]];
function C(id,cat,t,d,fields,fn,o){const x={id,cat,t,d,fields,fn,...o};CALC.push(x);CALCI[id]=x}
const ccToday=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())};
const cpmt=(P,r,n)=>r?P*r/(1-Math.pow(1+r,-n)):P/n;
function cbis(f,lo,hi){let a=lo,fa=f(a),b=hi;for(let i=0;i<200;i++){const m=(a+b)/2,fm=f(m);if((fm>0)===(fa>0)){a=m;fa=fm}else b=m}return(a+b)/2}
function cgrow(P,c,rate,m,yrs){const rm=Math.pow(1+rate/100/m,m/12)-1,n=Math.round(yrs*12),tab=[['Year','Total paid in','Interest earned','Balance']];let b=P,cont=P;
 for(let i=1;i<=n;i++){b=b*(1+rm)+c;cont+=c;if(i%12===0||i===n)tab.push([Math.ceil(i/12),cN(cont),cN(b-cont),cN(b)])}return{b,cont,tab}}
function camort(P,r,pay,extra){let b=P,m=0,I=0;const tab=[['Year','Interest paid','Principal paid','Balance']];let yi=0,yp=0;
 while(b>0.005&&m<1200){const i=b*r,p=Math.min(b,pay+(extra||0)-i);if(p<=0)throw'The payment is too small to ever pay off this loan.';b-=p;I+=i;yi+=i;yp+=p;m++;if(m%12===0||b<=0.005){tab.push([Math.ceil(m/12),cN(yi),cN(yp),cN(Math.max(0,b))]);yi=0;yp=0}}return{m,I,tab}}
const cnorm=z=>{const t=1/(1+0.2316419*Math.abs(z)),d=0.3989422804014327*Math.exp(-z*z/2),p=d*t*(0.31938153+t*(-0.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return z>0?1-p:p};
const cgcd=(a,b)=>{a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a};
const cList=s=>String(s).split(/[\s,;]+/).filter(Boolean).map(Number);
const cInt=(x,l)=>{if(!Number.isInteger(x))throw l+' must be a whole number.';return x};
const cNeed=(c,m)=>{if(!c)throw m};

/* ----- financial ----- */
const loanF=(t,d,def)=>C(t[0],'fin',t[1],d,[N('p','Loan amount',def[0]),N('r','Interest rate per year (%)',def[1]),N('y','Term (years)',def[2])],v=>{const n=Math.round(v.y*12);cNeed(n>0,'Enter a term of at least one month.');const pay=cpmt(v.p,v.r/1200,n);return[['Monthly payment',cN(pay),'big'],['Total of all payments',cN(pay*n)],['Total interest',cN(pay*n-v.p)],['Number of payments',String(n)]]});
loanF(['loan','Loan Calculator'],'Monthly payment and total interest for a fixed-rate loan.',[20000,7,5]);
loanF(['payment','Payment Calculator'],'Find the regular payment for any loan.',[15000,6,4]);
loanF(['repayment','Repayment Calculator'],'See what a loan repayment costs each month and in total.',[10000,8,3]);
loanF(['personal-loan','Personal Loan Calculator'],'Monthly payment for a personal loan.',[10000,11,3]);
loanF(['business-loan','Business Loan Calculator'],'Monthly payment for a business loan.',[50000,9,5]);
loanF(['boat-loan','Boat Loan Calculator'],'Monthly payment for a boat loan.',[40000,8,10]);
loanF(['student-loan','Student Loan Calculator'],'Monthly payment for a student loan (no grace period included).',[30000,5.5,10]);
C('mortgage','fin','Mortgage Calculator','Monthly home payment with tax, insurance and total interest.',[N('p','Home price',300000),N('dp','Down payment (%)',20),N('r','Interest rate per year (%)',6.5),N('y','Term (years)',30),N('tx','Property tax per year',3000),N('in','Home insurance per year',1200),N('hoa','Monthly HOA or other fees',0)],v=>{const L=v.p*(1-v.dp/100),n=Math.round(v.y*12),pi=cpmt(L,v.r/1200,n),tot=pi+v.tx/12+v.in/12+v.hoa;return[['Total monthly payment',cN(tot),'big'],['Principal and interest',cN(pi)],['Property tax (monthly)',cN(v.tx/12)],['Insurance (monthly)',cN(v.in/12)],['Loan amount',cN(L)],['Down payment',cN(v.p-L)],['Total interest over the loan',cN(pi*n-L)]]});
C('mortgage-canada','fin','Canadian Mortgage Calculator','Mortgage payment using semi-annual compounding, as Canadian lenders do.',[N('p','Home price',500000),N('dp','Down payment (%)',20),N('r','Interest rate per year (%)',5),N('y','Amortization (years)',25)],v=>{const L=v.p*(1-v.dp/100),n=Math.round(v.y*12),rm=Math.pow(1+v.r/200,1/6)-1,pay=cpmt(L,rm,n);return[['Monthly payment',cN(pay),'big'],['Loan amount',cN(L)],['Total interest',cN(pay*n-L)]]},{note:'Mortgage default insurance for down payments under 20% is not included.'});
C('mortgage-uk','fin','Mortgage Calculator UK','Repayment and interest-only monthly cost for a UK-style mortgage.',[N('p','Property price',300000),N('dp','Deposit (%)',15),N('r','Interest rate per year (%)',4.5),N('y','Term (years)',25)],v=>{const L=v.p*(1-v.dp/100),n=Math.round(v.y*12),pay=cpmt(L,v.r/1200,n);return[['Repayment mortgage, monthly',cN(pay),'big'],['Interest-only mortgage, monthly',cN(L*v.r/1200)],['Amount borrowed',cN(L)],['Total interest (repayment)',cN(pay*n-L)],['Loan to value',cP(100-v.dp,1)]]},{note:'Stamp duty, fees and rate changes after a fixed period are not included.'});
const amF=(id,t)=>C(id,'fin',t,'Year-by-year breakdown of interest, principal and balance.',[N('p','Loan amount',250000),N('r','Interest rate per year (%)',6),N('y','Term (years)',30),N('x','Extra payment per month',0)],v=>{const n=Math.round(v.y*12),r=v.r/1200,pay=cpmt(v.p,r,n),a=camort(v.p,r,pay,v.x);return[['Monthly payment',cN(pay),'big'],['Payoff time',cYM(a.m)],['Total interest',cN(a.I)],['Total paid',cN(v.p+a.I)],{title:'Yearly breakdown',table:a.tab}]});
amF('amortization','Amortization Calculator');amF('mortgage-amortization','Mortgage Amortization Calculator');
C('auto-loan','fin','Auto Loan Calculator','Monthly car payment including sales tax, trade-in and fees.',[N('p','Vehicle price',25000),N('dp','Down payment',3000),N('tr','Trade-in value',0),N('tx','Sales tax (%)',6),N('f','Fees',500),N('r','Interest rate per year (%)',6.5),N('m','Term (months)',60)],v=>{const L=v.p*(1+v.tx/100)+v.f-v.dp-v.tr;cNeed(L>0&&v.m>=1,'The loan amount must be above zero.');const pay=cpmt(L,v.r/1200,Math.round(v.m));return[['Monthly payment',cN(pay),'big'],['Amount financed',cN(L)],['Sales tax',cN(v.p*v.tx/100)],['Total interest',cN(pay*Math.round(v.m)-L)],['Total cost of the car',cN(pay*Math.round(v.m)+v.dp+v.tr)]]});
const leaseF=(id,t)=>C(id,'fin',t,'Estimate a monthly lease payment.',[N('msrp','Vehicle price (MSRP)',35000),N('cap','Negotiated price (cap cost)',33000),N('red','Down payment or rebates',2000),N('res','Residual value (% of MSRP)',60),N('m','Lease term (months)',36),N('apr','Lease interest rate per year (%)',5),N('tx','Sales tax on payment (%)',6)],v=>{const ac=v.cap-v.red,rv=v.msrp*v.res/100,dep=(ac-rv)/v.m,fin=(ac+rv)*v.apr/2400,pre=dep+fin;return[['Monthly payment (with tax)',cN(pre*(1+v.tx/100)),'big'],['Depreciation part',cN(dep)],['Finance part',cN(fin)],['Residual value',cN(rv)],['Money factor',cG(v.apr/2400)]]},{note:'Fees, taxes and mileage limits differ by dealer and region.'});
leaseF('lease','Lease Calculator');leaseF('auto-lease','Auto Lease Calculator');
C('mortgage-payoff','fin','Mortgage Payoff Calculator','See how extra payments shorten a loan and save interest.',[N('b','Current balance',200000),N('r','Interest rate per year (%)',6),N('y','Years remaining',25),N('x','Extra payment per month',200)],v=>{const n=Math.round(v.y*12),r=v.r/1200,pay=cpmt(v.b,r,n),a=camort(v.b,r,pay,0),e=camort(v.b,r,pay,v.x);return[['Time saved',cYM(a.m-e.m),'big'],['New payoff time',cYM(e.m)],['Interest saved',cN(a.I-e.I)],['Interest with extra payments',cN(e.I)],['Interest without extra payments',cN(a.I)],['Regular monthly payment',cN(pay)]]});
C('refinance','fin','Refinance Calculator','Check whether a new loan rate saves money after closing costs.',[N('b','Current balance',250000),N('r1','Current rate (%)',7),N('y1','Years remaining',27),N('r2','New rate (%)',5.5),N('y2','New term (years)',30),N('c','Closing costs',4000)],v=>{const p1=cpmt(v.b,v.r1/1200,Math.round(v.y1*12)),p2=cpmt(v.b,v.r2/1200,Math.round(v.y2*12)),s=p1-p2,i1=p1*Math.round(v.y1*12)-v.b,i2=p2*Math.round(v.y2*12)-v.b;return[['Monthly savings',cN(s),'big'],['Current payment',cN(p1)],['New payment',cN(p2)],['Break-even point',s>0?cYM(Math.ceil(v.c/s)):'No monthly saving'],['Total interest now vs. new',cN(i1)+' vs. '+cN(i2+v.c)+' (new includes closing costs)']]});
C('compound-interest','fin','Compound Interest Calculator','Growth of savings with regular deposits.',[N('p','Starting amount',10000),N('c','Monthly deposit',200),N('r','Interest rate per year (%)',5),N('y','Years',10),S('m','Compounded',[['12','Monthly'],['365','Daily'],['4','Quarterly'],['2','Half-yearly'],['1','Yearly']])],v=>{const g=cgrow(v.p,v.c,v.r,+v.m,v.y);return[['Future balance',cN(g.b),'big'],['Total paid in',cN(g.cont)],['Interest earned',cN(g.b-g.cont)],{title:'Year by year',table:g.tab}]});
C('savings','fin','Savings Calculator','How much your savings can grow.',[N('p','Starting balance',1000),N('c','Monthly deposit',150),N('r','Interest rate per year (%)',4),N('y','Years',5)],v=>{const g=cgrow(v.p,v.c,v.r,12,v.y);return[['Balance at the end',cN(g.b),'big'],['Total paid in',cN(g.cont)],['Interest earned',cN(g.b-g.cont)],{title:'Year by year',table:g.tab}]});
C('investment','fin','Investment Calculator','Future value of an investment, with an inflation-adjusted figure.',[N('p','Starting amount',5000),N('c','Monthly contribution',300),N('r','Expected return per year (%)',7),N('y','Years',20),N('i','Inflation per year (%)',2.5)],v=>{const g=cgrow(v.p,v.c,v.r,12,v.y);return[['Future value',cN(g.b),'big'],['In today\'s buying power',cN(g.b/Math.pow(1+v.i/100,v.y))],['Total paid in',cN(g.cont)],['Growth',cN(g.b-g.cont)],{title:'Year by year',table:g.tab}]},{note:'Returns are not guaranteed. This is an illustration, not advice.'});
C('simple-interest','fin','Simple Interest Calculator','Interest that does not compound.',[N('p','Principal',5000),N('r','Interest rate per year (%)',6),N('y','Years',3)],v=>[['Interest',cN(v.p*v.r/100*v.y),'big'],['Total amount',cN(v.p*(1+v.r/100*v.y))]]);
C('interest','fin','Interest Calculator','Compare simple and compound interest.',[N('p','Principal',10000),N('r','Interest rate per year (%)',5),N('y','Years',10)],v=>[['Simple interest',cN(v.p*v.r/100*v.y),'big'],['Compound interest (yearly)',cN(v.p*Math.pow(1+v.r/100,v.y)-v.p)],['Balance with simple interest',cN(v.p*(1+v.r/100*v.y))],['Balance with compound interest',cN(v.p*Math.pow(1+v.r/100,v.y))]]);
C('cd','fin','CD Calculator','Value of a fixed-term deposit at maturity.',[N('p','Deposit',10000),N('r','Interest rate per year (%)',4.5),N('m','Term (months)',12),S('c','Compounded',[['12','Monthly'],['365','Daily'],['4','Quarterly'],['1','Yearly']])],v=>{const a=v.p*Math.pow(1+v.r/100/+v.c,+v.c*v.m/12);return[['Value at maturity',cN(a),'big'],['Interest earned',cN(a-v.p)],['Effective yearly rate',cP((Math.pow(1+v.r/100/+v.c,+v.c)-1)*100)]]});
C('retirement','fin','Retirement Calculator','Will your savings last? Estimate your pot and monthly income.',[N('a','Your age',30),N('ra','Retirement age',60),N('s','Savings now',20000),N('c','Monthly saving',400),N('r','Return before retirement (% per year)',6),N('wa','Plan to age',85),N('r2','Return in retirement (% per year)',4)],v=>{cNeed(v.ra>v.a&&v.wa>v.ra,'Retirement age must be above your age and below the plan age.');const g=cgrow(v.s,v.c,v.r,12,v.ra-v.a),n=(v.wa-v.ra)*12,r=v.r2/1200;return[['Savings at retirement',cN(g.b),'big'],['Monthly income possible',cN(cpmt(g.b,r,n))],['Total paid in',cN(g.cont)],['Years of withdrawals',String(v.wa-v.ra)]]},{note:'An estimate only. Real returns, inflation and tax will differ.'});
C('401k','fin','401(k) Calculator','Retirement account growth with an employer match.',[N('s','Annual salary',60000),N('e','Your contribution (% of salary)',6),N('mt','Employer match (%)',50),N('ml','Match limit (% of salary)',6),N('g','Salary growth per year (%)',3),N('r','Return per year (%)',6),N('a','Your age',30),N('ra','Retirement age',65),N('b','Current balance',10000)],v=>{cNeed(v.ra>v.a,'Retirement age must be above your age.');let bal=v.b,sal=v.s,me=0,em=0;for(let y=0;y<v.ra-v.a;y++){const c=sal*v.e/100,m=sal*Math.min(v.e,v.ml)/100*v.mt/100;me+=c;em+=m;bal=bal*(1+v.r/100)+c+m;sal*=1+v.g/100}return[['Balance at retirement',cN(bal),'big'],['Your contributions',cN(me)],['Employer contributions',cN(em)],['Growth',cN(bal-v.b-me-em)]]},{note:'Contribution limits and rules depend on the country and year.'});
C('roi','fin','ROI Calculator','Return on investment and yearly rate.',[N('i','Amount invested',10000),N('f','Final value',14000),N('y','Years held',3)],v=>{cNeed(v.i>0,'The amount invested must be above zero.');return[['Return on investment',cP((v.f-v.i)/v.i*100),'big'],['Gain or loss',cN(v.f-v.i)],['Average yearly return',v.y>0&&v.f>0?cP((Math.pow(v.f/v.i,1/v.y)-1)*100):'—']]});
C('average-return','fin','Average Return Calculator','Compound yearly growth between two values.',[N('s','Starting value',10000),N('e','Ending value',18000),N('y','Years',6)],v=>{cNeed(v.s>0&&v.e>0&&v.y>0,'Values and years must be above zero.');return[['Compound yearly return',cP((Math.pow(v.e/v.s,1/v.y)-1)*100),'big'],['Total return',cP((v.e/v.s-1)*100)],['Simple average per year',cP((v.e/v.s-1)*100/v.y)]]});
C('future-value','fin','Future Value Calculator','What a sum and regular payments will be worth later.',[N('p','Present value',5000),N('c','Payment each period',100),N('r','Rate per year (%)',5),N('y','Years',10),S('n','Periods per year',['12','4','2','1'])],v=>{const n=+v.n,r=v.r/100/n,k=Math.round(v.y*n),fv=v.p*Math.pow(1+r,k)+(r?v.c*(Math.pow(1+r,k)-1)/r:v.c*k);return[['Future value',cN(fv),'big'],['Total paid in',cN(v.p+v.c*k)],['Interest earned',cN(fv-v.p-v.c*k)]]});
C('present-value','fin','Present Value Calculator','What a future sum is worth today.',[N('f','Future value',20000),N('r','Discount rate per year (%)',5),N('y','Years',10),S('n','Compounded per year',['1','2','4','12'])],v=>{const pv=v.f/Math.pow(1+v.r/100/+v.n,+v.n*v.y);return[['Present value',cN(pv),'big'],['Difference',cN(v.f-pv)]]});
