/* ----- calculator pages ----- */
const ccList=(x,raw)=>typeof x.fields==='function'?x.fields(raw||{}):x.fields;
function ccRawDef(x,raw){raw=Object.assign({},raw||{});const L=ccList(x,raw);L.forEach(f=>{if(f.k==='s'){if(!f.opts.some(o=>o[0]===raw[f.id]))raw[f.id]=f.d}else if(raw[f.id]===undefined)raw[f.id]=f.d===null||f.d===undefined?'':String(f.d);if(f.k==='u'&&raw[f.id+'_u']===undefined)raw[f.id+'_u']=String(f.u||0)});return raw}
function ccFieldHtml(f,raw){const id='cf_'+f.id,val=raw[f.id],lab=`<label for="${id}">${esc(f.l)}${f.opt?' <i>(optional)</i>':''}</label>`;let inp;
 if(f.k==='s')inp=`<select id="${id}">${f.opts.map(o=>`<option value="${esc(o[0])}"${o[0]===val?' selected':''}>${esc(o[1])}</option>`).join('')}</select>`;
 else if(f.k==='u')inp=`<div class="ccu"><input id="${id}" type="number" step="any" inputmode="decimal" value="${esc(val)}"><select id="${id}_u" aria-label="Unit">${f.units.map((u,i)=>`<option value="${i}"${String(i)===raw[f.id+'_u']?' selected':''}>${esc(u[0])}</option>`).join('')}</select></div>`;
 else if(f.k==='a')inp=`<textarea id="${id}" rows="${f.rows||4}" spellcheck="false">${esc(val)}</textarea>`;
 else if(f.k==='n')inp=`<input id="${id}" type="number" step="any" inputmode="decimal" value="${esc(val)}">`;
 else inp=`<input id="${id}" type="${{t:'text',d:'date',dt:'datetime-local',tm:'time'}[f.k]}" value="${esc(val)}"${f.k==='t'?' spellcheck="false" autocomplete="off"':''}>`;
 return `<div class="ccfld${f.k==='a'||f.big?' ccw':''}">${lab}${inp}</div>`}
function ccFormHtml(x,raw){return ccList(x,raw).map(f=>ccFieldHtml(f,raw)).join('')}
function ccReadRaw(x,old){const raw=Object.assign({},old||{});ccList(x,raw).forEach(f=>{const e=document.getElementById('cf_'+f.id);if(e)raw[f.id]=e.value;const u=document.getElementById('cf_'+f.id+'_u');if(u)raw[f.id+'_u']=u.value});return raw}
function ccParse(x,raw){const L=ccList(x,raw),v={};for(const f of L){const r=raw[f.id];if(f.k==='n'||f.k==='u'){const t=String(r).trim();if(t===''){if(f.opt){v[f.id]=null;continue}throw 'Enter a number for "'+f.l+'".'}const n=Number(t);if(!isFinite(n))throw 'Enter a valid number for "'+f.l+'".';if(f.k==='u'){const u=f.units[+raw[f.id+'_u']||0];v[f.id]=n*u[1];v[f.id+'_u']=u[0]}else v[f.id]=n}else{if(String(r).trim()===''&&!f.opt)throw 'Fill in "'+f.l+'".';v[f.id]=r}}return v}
let ccX=null,ccRaw={};
function ccRender(){const x=ccX,box=document.getElementById('ccres');if(!x||!box)return;let h;
 try{const v=ccParse(x,ccRaw),r=x.fn(v);h=r.map(i=>Array.isArray(i)?`<div class="ccr${i[2]==='big'?' big':''}"><span>${esc(i[0])}</span><b>${esc(i[1])}</b></div>`:i.table?`${i.title?`<h4>${esc(i.title)}</h4>`:''}<div class="cctw"><table class="lht cct"><thead><tr>${i.table[0].map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${i.table.slice(1).map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'').join('');
  if(x.gen||x.copy)h+=`<div class="lmb">${x.gen?'<button type="button" class="lbtn" onclick="ccRender()">Generate again</button>':''}<button type="button" class="lbtn o" onclick="ccCopy(this)">Copy result</button></div>`}
 catch(e){h=`<p class="ccerr" role="alert">${esc(typeof e==='string'?e:'Please check the numbers you entered.')}</p>`}
 box.innerHTML=h}
function ccCopy(b){const e=document.querySelector('#ccres .ccr b');if(!e)return;const t=e.textContent;try{navigator.clipboard.writeText(t).then(()=>{b.textContent='Copied';setTimeout(()=>b.textContent='Copy result',1500)},()=>{})}catch(x){}}
function calcInit(){const r=document.querySelector('.cc[data-x]');ccX=null;if(!r)return;const x=CALCI[r.dataset.x];if(!x)return;ccX=x;ccRaw=ccReadRaw(x,ccRawDef(x,{}));const f=document.getElementById('ccf');
 const on=e=>{if(!document.getElementById('ccf'))return;const first=ccList(x,ccRaw)[0],redraw=x.redraw&&e.target.id==='cf_'+first.id&&e.type==='change';ccRaw=ccReadRaw(x,ccRaw);if(redraw){ccRaw=ccRawDef(x,ccRaw);f.innerHTML=ccFormHtml(x,ccRaw);ccRaw=ccReadRaw(x,ccRaw)}ccRender()};
 f.addEventListener('input',on);f.addEventListener('change',on);ccRender()}
function calcPg(slug){const x=CALCI[slug];
 if(!x){document.title='Calculators — The Sujan Khadka';const note=CALC.length;
  return `<div class="lrn"><section class="tlh"><h1>Calculators</h1><p>${note} free calculators for money, health, maths and everyday jobs. Everything runs in your browser, so nothing you type is sent anywhere.</p></section>
  <div class="ccsrch"><label for="ccq" class="ccsl">Search calculators</label><input id="ccq" type="search" placeholder="Try: mortgage, BMI, percentage, age…" oninput="ccFilter(this.value)" autocomplete="off"></div><p id="ccn" class="lsm" aria-live="polite"></p>
  ${CCATS.map(c=>{const L=CALC.filter(y=>y.cat===c[0]);return `<section class="ccsec"><h2 class="lh2">${c[1]} <small>(${L.length})</small></h2><div class="lgrid">${L.map(y=>`<a class="lcard ccard" href="/calculators/${y.id}" data-t="${esc((y.t+' '+y.d).toLowerCase())}"><b>${esc(y.t)}</b><span class="ld">${esc(y.d)}</span></a>`).join('')}</div></section>`}).join('')}
  <p class="lnote lw">These calculators give estimates for learning and planning. They are not financial, medical or legal advice. Rules, taxes and rates differ by country, so check with a qualified person before making big decisions.</p></div>`}
 document.title=x.t+' — Calculators — The Sujan Khadka';const raw=ccRawDef(x,{}),rel=CALC.filter(y=>y.cat===x.cat&&y.id!==x.id),i=Math.max(0,rel.findIndex(y=>CALC.indexOf(y)>CALC.indexOf(x))),near=rel.slice(i,i+6).concat(rel.slice(0,Math.max(0,6-rel.slice(i,i+6).length)));
 return `<div class="lrn cc" data-x="${x.id}"><section class="tlh"><a class="lbk" href="/calculators">← All calculators</a><h1>${esc(x.t)}</h1><p>${esc(x.d)}</p></section>
 <div class="ccbox"><div id="ccf" class="ccf">${ccFormHtml(x,raw)}</div></div>
 <div class="ccbox ccout" id="ccres" aria-live="polite"></div>
 ${x.note?`<p class="lnote lw">${esc(x.note)}</p>`:''}<p class="lnote lw">Estimates only. This is not financial, medical or legal advice.</p>
 <h2 class="lh2">More ${esc((CCATS.find(c=>c[0]===x.cat)||['',''])[1].toLowerCase())} calculators</h2><div class="lgrid">${near.map(y=>`<a class="lcard ccard" href="/calculators/${y.id}"><b>${esc(y.t)}</b><span class="ld">${esc(y.d)}</span></a>`).join('')}</div></div>`}
function ccFilter(q){q=q.trim().toLowerCase();let n=0;document.querySelectorAll('.ccard[data-t]').forEach(a=>{const ok=!q||q.split(/\s+/).every(w=>a.dataset.t.includes(w));a.hidden=!ok;if(ok)n++});document.querySelectorAll('.ccsec').forEach(s=>{s.hidden=!s.querySelector('.ccard:not([hidden])')});const e=document.getElementById('ccn');if(e)e.textContent=q?(n?n+' calculator'+(n===1?'':'s')+' found.':'No calculator matches "'+q+'". Try a shorter word.'):''}

